  "Dates are not held until the host pre-approves. Do not send payment yet.": "Die Daten sind erst nach der Vorabgenehmigung des Gastgebers reserviert. Senden Sie noch keine Zahlung.",
  "Dates are not held yet. Pre-approval sends the tenant one request for their identity and payment. Choose how long they have to complete both.": "Die Termine sind noch nicht reserviert. Mit der Vorabgenehmigung erhält der Mieter eine Anfrage für Identität und Zahlung. Legen Sie fest, wie lange er Zeit hat, beides abzuschließen.",
  "Dates held · {0}h {1}m left to report payment. Deadline: {2}, Colombia time.": "Daten reserviert · noch {0} h {1} min, um die Zahlung zu melden. Frist: {2}, Ortszeit Kolumbien.",
  "Days after the agreed move-out. You return it, not us. Saying it up front is what stops the argument at the end.": "Tage nach dem vereinbarten Auszug. Sie zahlen sie zurück, nicht wir. Wer das vorab klärt, vermeidet den Streit am Ende.",
