  "E.g. software engineer working remotely, moving from Chicago, quiet, no smoking, looking for somewhere for at least a year in Laureles.": "Z. B. Softwareentwickler, arbeite remote, ziehe aus Chicago um, ruhig, Nichtraucher, suche etwas für mindestens ein Jahr in Laureles.",
  "E.g. three bedrooms, 120 square metres, eighth floor with a balcony, renovated kitchen, two parking spaces, estrato 5, building from 2015.": "Z. B. drei Schlafzimmer, 120 Quadratmeter, achter Stock mit Balkon, renovierte Küche, zwei Stellplätze, estrato 5, Baujahr 2015.",
  "E.g. two bedrooms, tenth floor, morning light, quiet street, five minutes' walk to Parque Lleras, building has a gym and 24-hour porter.": "Z. B. zwei Schlafzimmer, zehnter Stock, Morgensonne, ruhige Straße, fünf Gehminuten zum Parque Lleras, Gebäude mit Fitnessraum und 24-Stunden-Pförtner.",
  "Each missing detail must be completed where it is managed. The agreement stays in draft until all required details are available.": "Jede fehlende Angabe muss dort ergänzt werden, wo sie verwaltet wird. Der Vertrag bleibt im Entwurf, bis alle erforderlichen Angaben vorliegen.",
  "Each person signs from their own account, using this email.": "Jede Person unterschreibt über ihr eigenes Konto mit dieser E-Mail-Adresse.",
