  "Event sharing is coming soon": "Das Teilen von Events ist bald verfügbar",
  "Every agent here carries a OneScore built from work they have actually completed — across renting, jobs and events. It is the part a WhatsApp group cannot give you.": "Jeder Makler hier hat einen OneScore, der auf tatsächlich abgeschlossener Arbeit beruht — beim Vermieten, bei Jobs und Events. Das ist es, was Ihnen keine WhatsApp-Gruppe bieten kann.",
  "Every agent here carries a OneScore built from work they have actually completed — across selling, renting, jobs and events. It is the part a WhatsApp group cannot give you.": "Jeder Makler hier hat einen OneScore, der auf tatsächlich abgeschlossener Arbeit beruht — bei Verkauf, Vermietung, Jobs und Events. Das kann Ihnen keine WhatsApp-Gruppe bieten.",
  "Every lease and sale agreement you sign lands here, ready to share or print.": "Jeder Miet- und Kaufvertrag, den Sie unterschreiben, landet hier, bereit zum Teilen oder Drucken.",
  "Every lease and sale agreement you've signed — share, save or print.": "Jeder Miet- und Kaufvertrag, den Sie unterschrieben haben — teilen, speichern oder drucken.",
  "Every price shown is per month.": "Alle angezeigten Preise gelten pro Monat.",
  "Every price shown is per night.": "Alle angezeigten Preise gelten pro Nacht.",
  "Every registered sale on this folio — what it actually changed hands for, the deed number and the notaría — is pulled from the national registry and shown on your listing. Nobody else in Colombia puts that in front of a buyer.": "Jeder eingetragene Verkauf auf diesem Folio — der tatsächliche Verkaufspreis, die Urkundennummer und die Notaría — wird aus dem nationalen Register abgerufen und in Ihrem Inserat angezeigt. Niemand sonst in Kolumbien zeigt das einem Käufer.",
  "Everything above is exactly what a buyer will see.": "Alles oben sieht ein Käufer genau so.",
  "Everything above is exactly what a tenant will see.": "Alles oben sieht ein Mieter genau so.",
  "Everything you have listed, to let and to sell. Tap any one to open its listing.": "Alles, was Sie zur Miete und zum Verkauf inseriert haben. Tippen Sie auf eines, um das Inserat zu öffnen.",
  "Everything you've hearted, rent and sale together.": "Alles, was Sie mit Herz markiert haben, Miete und Kauf zusammen.",
  "Everything you've hearted, sale and rent together.": "Alles, was Sie mit einem Herz markiert haben, Kauf und Miete zusammen.",
  "Excellent": "Ausgezeichnet",
  "Existing stay: August 29 onward is available. For September rent, select September 1 and October 1 (checkout). August proration is separate.": "Bestehender Aufenthalt: ab 29. August verfügbar. Für die Septembermiete wählen Sie den 1. September und den 1. Oktober (Auszug). Die anteilige Augustmiete wird separat berechnet.",
  "Expired": "Abgelaufen",
