  "Families search on this before anything else.": "Danach suchen Familien als Allererstes.",
  "Fill in this addendum": "Diesen Nachtrag ausfüllen",
  "Fill it in once and apply to any place in one tap.": "Einmal ausfüllen und sich mit einem Tippen für jede Unterkunft bewerben.",
  "Fill them in": "Ausfüllen",
  "Fill this in once. Every place you enquire about gets a complete application instead of a message asking if it's still available — which is how you get answered first.": "Einmal ausfüllen. Jede Unterkunft, für die Sie sich interessieren, erhält eine vollständige Bewerbung statt einer Nachricht wie „Ist das noch frei?“ — so bekommen Sie als Erstes eine Antwort.",
