  "Held until the closing date, up to six months. Every movement is timestamped and both sides see it.": "Wird bis zum Abschlussdatum verwahrt, höchstens sechs Monate. Jede Bewegung hat einen Zeitstempel, und beide Seiten sehen sie.",
  "Help requests open 24 hours after reporting an external payment, while receipt remains unconfirmed.": "Hilfeanfragen sind 24 Stunden nach der Meldung einer externen Zahlung möglich, solange der Eingang unbestätigt ist.",
