  "I agree these photos are accurate": "Ich bestätige, dass diese Fotos zutreffend sind",
  "I agree to receive reservation texts at my verified phone. Message and data rates may apply. Turn this off here at any time.": "Ich bin einverstanden, Reservierungs-SMS an meine bestätigte Telefonnummer zu erhalten. Es können Gebühren für Nachrichten und Daten anfallen. Sie können dies hier jederzeit deaktivieren.",
  "I agree to sign this agreement electronically.": "Ich stimme zu, diesen Vertrag elektronisch zu unterschreiben.",
  "I am authorized to offer this property and everything in this listing is accurate.": "Ich bin berechtigt, diese Immobilie anzubieten, und alle Angaben in diesem Inserat sind korrekt.",
  "I am coming with my partner.": "Ich komme mit meinem Partner.",
  "I am the owner of this property, or authorised by the owner to offer it for sale, and everything in this listing is accurate.": "Ich bin Eigentümer dieser Immobilie oder vom Eigentümer bevollmächtigt, sie zum Verkauf anzubieten, und alle Angaben in diesem Inserat sind korrekt.",
  "I can get a rent guarantee policy": "Ich kann eine Mietgarantieversicherung abschließen",
