  "I have pets": "Ich habe Haustiere",
  "I understand": "Verstanden",
  "I understand: these clauses are optional. Tap a card to add it, and tap it again to remove it.": "Verstanden: Diese Klauseln sind optional. Tippen Sie auf eine Karte, um sie hinzuzufügen, und erneut, um sie zu entfernen.",
  "Identity": "Identität",
  "Identity checked by OneHome": "Identität von OneHome geprüft",
  "Identity is linked from the tenant's One ID. Adjust only the dates or terms if you are making a special offer.": "Die Identität stammt aus der One ID des Mieters. Ändern Sie nur die Termine oder Bedingungen, wenn Sie ein Sonderangebot machen.",
  "Identity review is still required before final approval.": "Vor der endgültigen Genehmigung ist noch eine Identitätsprüfung erforderlich.",
  "If the problem cannot be seen — the air conditioner is not blowing cold air — photograph it anyway and say so here. A caption is what turns a photo into evidence.": "Wenn das Problem nicht sichtbar ist — die Klimaanlage kühlt nicht —, fotografieren Sie es trotzdem und schreiben Sie es hier dazu. Erst die Beschreibung macht ein Foto zum Beweis.",
  "If the window closes with photos that were never answered, the photos stand as the record and the silence is recorded with them. If nobody submitted anything, there is no move-in record — and with no record, nothing can be deducted from the deposit at the end.": "Endet die Frist mit unbeantworteten Fotos, gelten die Fotos als Nachweis, und das Schweigen wird mit ihnen festgehalten. Hat niemand etwas eingereicht, gibt es kein Einzugsprotokoll — und ohne Protokoll kann am Ende nichts von der Kaution abgezogen werden.",
  "If they move in mid-month, the part-month at the start.": "Bei Einzug zur Monatsmitte: der anteilige Monat zu Beginn.",
  "If you both agree, it can reopen once for another 48 hours.": "Wenn Sie beide zustimmen, kann es einmal für weitere 48 Stunden wieder geöffnet werden.",
  "If you opened the link in the same email, the code was already used — they are one and the same. Send a fresh one and type it without opening the link.": "Wenn Sie den Link in derselben E-Mail geöffnet haben, wurde der Code bereits verwendet — beides ist ein und dasselbe. Fordern Sie einen neuen an und geben Sie ihn ein, ohne den Link zu öffnen.",
  "Important information about Colombian deposit law": "Wichtige Informationen zum kolumbianischen Kautionsrecht",
  "In the building": "Im Gebäude",
  "In your comparison": "In Ihrem Vergleich",
  "Include my own terms or contract? (optional)": "Eigene Bedingungen oder eigenen Vertrag beifügen? (optional)",
  "Included with every account": "In jedem Konto enthalten",
  "Includes a {0} guest service fee.": "Inklusive einer Gästeservicegebühr von {0}.",
  "Instagram doesn't show links in posts, so it gets a picture with the link printed on it — and the link is copied for the Link sticker.": "Instagram zeigt in Beiträgen keine Links an. Deshalb gibt es ein Bild mit aufgedrucktem Link — und der Link wird für den Link-Sticker kopiert.",
  "Introduce me": "Kontakt vermitteln",
  "It happened": "Hat stattgefunden",
