  "It may have been turned off or replaced. Ask them to show you a current one.": "Er wurde möglicherweise deaktiviert oder ersetzt. Bitten Sie die Person, Ihnen einen aktuellen zu zeigen.",
  "It will read": "Es wird lauten",
