  "Leave without saving? Anything you have typed here will be lost.": "Ohne Speichern verlassen? Alles, was Sie hier eingegeben haben, geht verloren.",
  "Leaves the draft above untouched.": "Der Entwurf oben bleibt unverändert.",
  "Let me share this with a code or link": "Teilen per Code oder Link erlauben",
  "Let people book a viewing": "Besichtigungen buchbar machen",
  "Let the public comment on this listing": "Öffentliche Kommentare zu diesem Inserat erlauben",
  "Ley 820 de 2003 (Article 16) says a landlord may not require a cash deposit on a residential lease of 30 days or more. A tenant can ask for it back at any time and the clause has no force. OneHome does not collect it, hold it, or return it, and takes no fee on it — it is paid to you directly and it is between you and the tenant. The tenant is told all of this on your listing.": "Ley 820 de 2003 (Artikel 16) besagt, dass ein Vermieter bei einem Wohnraummietvertrag von 30 Tagen oder länger keine Barkaution verlangen darf. Ein Mieter kann sie jederzeit zurückfordern, und die Klausel ist unwirksam. OneHome zieht sie nicht ein, verwahrt sie nicht, zahlt sie nicht zurück und erhebt keine Gebühr darauf — sie wird direkt an Sie gezahlt und ist eine Sache zwischen Ihnen und dem Mieter. Der Mieter wird in Ihrem Inserat über all das informiert.",
