  "Pre-approve this tenant. OneHome will ask them for their identity and payment in the same request.": "Diesen Mieter vorab genehmigen. OneHome fragt in derselben Anfrage nach Identität und Zahlung.",
  "Pre-approved · ID complete · payment confirmation pending": "Vorab genehmigt · Ausweis vollständig · Zahlungsbestätigung ausstehend",
  "Pre-approved · waiting for the tenant's ID": "Vorab genehmigt · wartet auf den Ausweis des Mieters",
  "Preview & publish": "Vorschau & veröffentlichen",
  "Preview — this is the listing exactly as a tenant sees it. It is not live yet.": "Vorschau — so sieht ein Mieter das Inserat. Es ist noch nicht online.",
  "Previous month": "Vorheriger Monat",
  "Price and commission": "Preis und Provision",
