  "Private move-in evidence": "Private Einzugsnachweise",
  "Private note (optional)": "Private Notiz (optional)",
  "Private photos and videos for owner–tenant sign-off.": "Private Fotos und Videos zur Abnahme durch Eigentümer und Mieter.",
  "Private until a buyer is serious.": "Privat, bis ein Käufer ernsthaft interessiert ist.",
  "Private walkthrough viewer": "Private Protokollansicht",
  "Private. It is never shown on your public profile or listing.": "Privat. Wird nie in Ihrem öffentlichen Profil oder Inserat angezeigt.",
  "Private. Only the neighbourhood is shown publicly — the exact address goes to the tenant once a contract exists.": "Privat. Öffentlich wird nur das Viertel angezeigt — die genaue Adresse erhält der Mieter, sobald ein Vertrag besteht.",
  "Pro applies to this app. VIP applies to every One World app for one price. Both renew monthly, and cancelling keeps you on the plan until the period you have already paid for ends.": "Pro gilt für diese App. VIP gilt für alle One World Apps zu einem Preis. Beide verlängern sich monatlich, und nach einer Kündigung bleiben Sie im Tarif, bis der bereits bezahlte Zeitraum endet.",
  "Pro on OneHome. See what VIP adds.": "Pro für OneHome. Sehen Sie, was VIP bietet.",
