  "Queen": "Queen-Size",
  "Questions and answers show under the listing, where the next person can read them. Turn it off and only you can post — anything already there stays visible.": "Fragen und Antworten erscheinen unter dem Inserat, wo die nächste Person sie lesen kann. Ist es aus, können nur Sie posten — alles Vorhandene bleibt sichtbar.",
