  "Shows places free from your arrival date whose minimum stay fits. It cannot see a host's existing bookings yet, so confirm the dates with them.": "Zeigt Unterkünfte, die ab Ihrem Anreisedatum frei sind und deren Mindestaufenthalt passt. Bestehende Buchungen des Gastgebers sind noch nicht sichtbar, bestätigen Sie die Daten daher mit ihm.",
