  "Somebody could book a viewing for later today.": "Jemand könnte noch für heute eine Besichtigung buchen.",
  "Somebody just took that time. Here are the times still free.": "Diese Zeit wurde gerade vergeben. Hier sind die noch freien Zeiten.",
  "Someone in Colombia who'll guarantee the lease.": "Eine Person in Kolumbien, die für den Mietvertrag bürgt.",
  "Someone is always there": "Immer jemand vor Ort",
  "Something is wrong": "Etwas stimmt nicht",
  "Something on OneHome still points at this place - usually a contract - so it cannot be deleted. That link is what keeps those records readable for everyone on them. Archive it instead: it leaves your working list and public search, and every record stays intact.": "Etwas auf OneHome verweist noch auf diese Unterkunft - meist ein Vertrag -, daher kann sie nicht gelöscht werden. Diese Verknüpfung sorgt dafür, dass die Unterlagen für alle Beteiligten lesbar bleiben. Archivieren Sie sie stattdessen: Sie verschwindet aus Ihrer Arbeitsliste und der öffentlichen Suche, und alle Unterlagen bleiben erhalten.",
  "Sort": "Sortieren",
  "Sort by": "Sortieren nach",
  "Source: IGAC / national property registry, open data · matrícula ": "Quelle: IGAC / nationales Immobilienregister, offene Daten · matrícula ",
