  "Stay until {0} instead of {1}.": "Bleiben Sie bis {0} statt bis {1}.",
  "Stays under 30 nights are lodging, not a home lease, so a card hold is the right instrument and the only one offered here.": "Aufenthalte unter 30 Nächten gelten als Beherbergung, nicht als Wohnraummiete. Daher ist eine Kartenreservierung das passende Mittel und hier die einzige Option.",
