  "Submission could not be confirmed. Refresh the request before trying again.": "Die Übermittlung konnte nicht bestätigt werden. Aktualisieren Sie die Anfrage, bevor Sie es erneut versuchen.",
  "Submission could not be confirmed. Your private ID was retained; please refresh the request before trying again.": "Die Übermittlung konnte nicht bestätigt werden. Ihr privater Ausweis wurde gespeichert; bitte aktualisieren Sie die Anfrage, bevor Sie es erneut versuchen.",
  "Submit ID to the host": "Ausweis an Gastgeber senden",
  "Submit rental request": "Mietanfrage senden",
  "Submit your passport or government ID": "Reisepass oder amtlichen Ausweis einreichen",
  "Submitted": "Eingereicht",
  "Submitting is not final approval and does not guarantee the home.": "Das Absenden ist keine endgültige Zusage und garantiert die Unterkunft nicht.",
  "Submitting this request does not hold the dates. The hold starts when the host pre-approves.": "Mit dem Senden dieser Anfrage werden die Daten nicht reserviert. Die Reservierung beginnt mit der Vorabgenehmigung durch den Gastgeber.",
  "Submitting…": "Wird gesendet…",
  "Suggestions applied. Review the form, then save the draft or publish.": "Vorschläge übernommen. Prüfen Sie das Formular und speichern Sie dann den Entwurf oder veröffentlichen Sie ihn.",
  "TRM certified by the Superintendencia Financiera, in force {0}.": "TRM, zertifiziert von der Superintendencia Financiera, gültig ab {0}.",
  "TRM certified by the Superintendencia Financiera, in force {0}. Saved with the listing so the price you set today still reads honestly in six months.": "TRM, zertifiziert von der Superintendencia Financiera, gültig ab {0}. Wird mit dem Inserat gespeichert, damit der heute festgelegte Preis auch in sechs Monaten noch ehrlich dargestellt wird.",
  "Take or choose photos": "Fotos aufnehmen oder auswählen",
  "Tap and hold to react": "Gedrückt halten, um zu reagieren",
  "Tap any amber blank to jump to the field that fills it.": "Tippen Sie auf eine gelbe Lücke, um zum zugehörigen Feld zu springen.",
  "Tap the heart on any listing and it lands here — so you can put four places side by side instead of scrolling back to find them.": "Tippen Sie bei einem Inserat auf das Herz, und es landet hier — so können Sie vier Unterkünfte nebeneinander vergleichen, statt zurückzuscrollen und sie zu suchen.",
  "Tap to add": "Zum Hinzufügen tippen",
  "Tap to remove": "Zum Entfernen tippen",
  "Tap to send voice note": "Tippen Sie, um die Sprachnachricht zu senden",
  "Tell the tenant what needs to be corrected.": "Teilen Sie dem Mieter mit, was korrigiert werden muss.",
  "Tell them about your pets": "Erzählen Sie von Ihren Haustieren",
  "Tell them what it is actually like to live there — the light, the noise, the walk to the shops.": "Erzählen Sie, wie es sich dort wirklich wohnt — das Licht, der Lärm, der Weg zum Einkaufen.",
  "Tenant": "Mieter",
  "Tenant ID type": "Ausweisart des Mieters",
