  "Try changing your search or filters.": "Ändern Sie Ihre Suche oder Filter.",
  "Turn your phone sideways for more room": "Drehen Sie Ihr Telefon quer, um mehr Platz zu haben",
  "Twelve years in El Poblado. I answer messages the same day.": "Zwölf Jahre in El Poblado. Ich beantworte Nachrichten am selben Tag.",
  "Two or three lines. This is what makes an agent reply — who you are, why you're moving, how long you plan to stay.": "Zwei oder drei Zeilen. Das bringt Makler zum Antworten — wer Sie sind, warum Sie umziehen, wie lange Sie bleiben möchten.",
  "Two separate machines": "Zwei separate Geräte",
  "Two sinks in the bathroom": "Zwei Waschbecken im Bad",
  "Type of property": "Immobilientyp",
  "Type your name and sign with your finger. The signed copy is stamped with your name and the exact time, and cannot be changed by anyone afterwards.": "Geben Sie Ihren Namen ein und unterschreiben Sie mit dem Finger. Die unterschriebene Kopie wird mit Ihrem Namen und der genauen Uhrzeit versehen und kann danach von niemandem geändert werden.",
  "Unavailable dates could not be loaded. The calendar may be incomplete.": "Nicht verfügbare Daten konnten nicht geladen werden. Der Kalender ist möglicherweise unvollständig.",
  "Unavailable from": "Nicht verfügbar ab",
  "Under $1,000 / month": "Unter $1,000 / Monat",
  "Under offer": "Reserviert",
  "Under {0} years old": "Jünger als {0} Jahre",
  "Unfurnished": "Unmöbliert",
