  "Untitled property": "Unbenannte Immobilie",
  "Up to 100 photos and 10 videos (five minutes each). Select large batches; original evidence quality is retained for pinch-to-zoom.": "Bis zu 100 Fotos und 10 Videos (je fünf Minuten). Wählen Sie große Mengen auf einmal aus; die Originalqualität bleibt für das Zoomen mit zwei Fingern erhalten.",
  "Up to 5 public videos. Portrait and landscape clips both open full screen.": "Bis zu 5 öffentliche Videos. Hoch- und Querformat öffnen beide im Vollbild.",
  "Up to {0}": "Bis {0}",
  "Up to {0} characters on the free plan.": "Bis zu {0} Zeichen im kostenlosen Tarif.",
  "Up to {0} characters on your {1} plan. This is the caption people read in the feed.": "Bis zu {0} Zeichen in Ihrem {1}-Tarif. Dies ist die Bildunterschrift, die andere im Feed lesen.",
  "Up to {0} videos · 5 minutes and 300 MB each · resumable uploads": "Bis zu {0} Videos · je 5 Minuten und 300 MB · fortsetzbare Uploads",
  "Up to {0}. The first is the cover unless you choose another below.": "Bis zu {0}. Das erste ist das Titelbild, sofern Sie unten kein anderes wählen.",
  "Upload your agreement": "Ihren Vertrag hochladen",
  "Upload, paste or link an existing document. You will review every suggestion before it becomes part of this property's agreement.": "Laden Sie ein vorhandenes Dokument hoch, fügen Sie es ein oder verlinken Sie es. Sie prüfen jeden Vorschlag, bevor er Teil des Vertrags für diese Unterkunft wird.",
  "Use a 6-digit email code": "6-stelligen E-Mail-Code verwenden",
  "Use a JPG, PNG, WebP or PDF no larger than 15 MB.": "Verwenden Sie eine JPG-, PNG-, WebP- oder PDF-Datei mit höchstens 15 MB.",
  "Use password instead": "Stattdessen Passwort verwenden",
  "Use this for repairs, personal stays, or any date you cannot host. The available-again date is not blocked.": "Nutzen Sie dies für Reparaturen, eigene Aufenthalte oder jedes Datum, an dem Sie keine Gäste aufnehmen können. Das Datum „Wieder verfügbar“ wird nicht blockiert.",
  "Using OneHome's standard agreement. No supplemental owner terms were enabled for this property.": "Es wird der Standardvertrag von OneHome verwendet. Für diese Immobilie wurden keine zusätzlichen Eigentümerbedingungen aktiviert.",
  "Usually replies within a day": "Antwortet meist innerhalb eines Tages",
  "Usually replies within a few hours": "Antwortet meist innerhalb weniger Stunden",
  "Usually replies within an hour": "Antwortet meist innerhalb einer Stunde",
  "Usually replies within {0} days": "Antwortet meist innerhalb von {0} Tagen",
  "VIP already covers every app, including this one.": "VIP deckt bereits jede App ab, auch diese.",
