  "Voice recording is not available here.": "Sprachaufnahme ist hier nicht verfügbar.",
  "Voice recording stopped unexpectedly.": "Die Sprachaufnahme wurde unerwartet beendet.",
  "Waiting for signatures": "Wartet auf Unterschriften",
  "Waiting for signatures · {0} of {1}": "Wartet auf Unterschriften · {0} von {1}",
  "Waiting for the other party to acknowledge. Renewals are paused.": "Bestätigung der anderen Seite ausstehend. Verlängerungen sind pausiert.",
  "Waiting for the other party to answer this one.": "Warten auf die Antwort der anderen Partei.",
  "Waiting for the tenant to confirm they have sent the rent. You can mark it received after that.": "Warten auf die Bestätigung des Mieters, dass er die Miete überwiesen hat. Danach können Sie sie als erhalten markieren.",
  "Waiting for today's official rate — prices stay in dollars until it loads rather than being converted at a guess.": "Warten auf den heutigen offiziellen Kurs — die Preise bleiben in Dollar, bis er geladen ist, statt geschätzt umgerechnet zu werden.",
  "Waiting on the other party.": "Warten auf die andere Partei.",
  "Walk through every section": "Alle Abschnitte durchgehen",
  "Washer + separate dryer unit": "Waschmaschine + separater Trockner",
  "Washer-dryer combo unit": "Waschtrockner",
  "Water tank": "Wassertank",
  "We could not run the bot check here. You can still continue.": "Die Bot-Prüfung konnte hier nicht ausgeführt werden. Sie können trotzdem fortfahren.",
  "We couldn't confirm sign-out on all devices. Try again.": "Die Abmeldung auf allen Geräten konnte nicht bestätigt werden. Versuchen Sie es erneut.",
  "We couldn't confirm that was saved. Your link is still here — try Save again.": "Wir konnten nicht bestätigen, dass gespeichert wurde. Ihr Link ist noch da — tippen Sie erneut auf Speichern.",
  "We couldn't reach the official rate just now, so this listing will show US dollars only. Nothing is estimated.": "Wir konnten den offiziellen Kurs gerade nicht abrufen, daher zeigt dieses Inserat nur US-Dollar an. Nichts wird geschätzt.",
  "We couldn't reach the official rate just now. The listing will stay in {0}; no conversion will be guessed.": "Wir konnten den offiziellen Kurs gerade nicht abrufen. Das Inserat bleibt in {0}; es wird keine Umrechnung geschätzt.",
  "We never hold the purchase price.": "Wir verwahren nie den Kaufpreis.",
  "We'll send one six-digit code.": "Wir senden Ihnen einen sechsstelligen Code.",
  "Weekly stay discount": "Rabatt für Wochenaufenthalte",
  "Welcome back": "Willkommen zurück",
  "What a buyer sees beside your properties.": "Was ein Käufer neben Ihren Immobilien sieht.",
  "What a seller sees when you ask about their property.": "Was ein Verkäufer sieht, wenn Sie nach seiner Immobilie fragen.",
  "What is wrong? e.g. the ceiling fan is broken": "Was ist defekt? z. B. der Deckenventilator ist kaputt",
  "What it covers and when it comes back. The tenant sees this.": "Was sie abdeckt und wann sie zurückgezahlt wird. Der Mieter sieht das.",
  "What it shows": "Was es zeigt",
  "What makes this one worth seeing — the light, the layout, what the neighbourhood is like.": "Was diese Immobilie sehenswert macht — das Licht, der Grundriss, wie die Nachbarschaft ist.",
  "What moves through the app": "Was über die App läuft",
  "What places actually cost here": "Was Unterkünfte hier wirklich kosten",
  "What places actually sold for": "Wofür Immobilien tatsächlich verkauft wurden",
  "What reaches you": "Was bei Ihnen ankommt",
  "What secures it": "Absicherung",
  "What secures the lease": "Absicherung des Mietvertrags",
  "What that covers": "Wofür das ist",
  "What the numbers say": "Was die Zahlen sagen",
  "What the owner pays the building every month for security, lifts, common areas and repairs. Buyers compare this as closely as the price.": "Was der Eigentümer dem Gebäude monatlich für Sicherheit, Aufzüge, Gemeinschaftsflächen und Reparaturen zahlt. Käufer vergleichen das ebenso genau wie den Preis.",
  "What this is": "Worum es geht",
  "What this place has": "Ausstattung",
  "What you do": "Was Sie machen",
  "What's booked, and when each place frees up.": "Was gebucht ist und wann jede Unterkunft wieder frei wird.",
  "When the buyer can actually move in.": "Wann der Käufer tatsächlich einziehen kann.",
  "When you sign off you are agreeing this is how the property is right now. Once both of you sign off, these photos are locked and cannot be changed by anyone.": "Mit Ihrer Bestätigung erklären Sie, dass die Immobilie jetzt so aussieht. Sobald Sie beide bestätigt haben, sind diese Fotos gesperrt und können von niemandem mehr geändert werden.",
  "When, and for how long": "Wann und wie lange",
  "Where": "Wo",
  "Where a legal notice about a lease reaches you. Colombian leases must name one for each side, and it cannot be the property you are letting. Never public, never shown on a listing, and it appears only on a lease you have signed.": "Wo Sie rechtliche Mitteilungen zu einem Mietvertrag erreichen. Kolumbianische Mietverträge müssen für jede Partei eine solche Adresse nennen, und es darf nicht die vermietete Immobilie sein. Nie öffentlich, nie in einem Inserat sichtbar und erscheint nur in einem Mietvertrag, den Sie unterschrieben haben.",
