  "You are already on this plan.": "Sie haben diesen Tarif bereits.",
  "You are paying the host outside OneHome. OneHome does not hold these funds and cannot guarantee a refund or reverse the transfer. Recovery depends on the provider and payment status. Confirm the host, recipient, amount and reservation before sending. Wait for pre-approval and keep your receipt.": "Sie bezahlen den Gastgeber außerhalb von OneHome. OneHome verwahrt dieses Geld nicht und kann weder eine Rückerstattung garantieren noch die Überweisung rückgängig machen. Ob das Geld zurückgeholt werden kann, hängt vom Anbieter und vom Zahlungsstatus ab. Prüfen Sie Gastgeber, Empfänger, Betrag und Reservierung, bevor Sie senden. Warten Sie auf die Vorabgenehmigung und bewahren Sie Ihren Beleg auf.",
  "You are signed in as a different account now. Nothing was saved.": "Sie sind jetzt mit einem anderen Konto angemeldet. Es wurde nichts gespeichert.",
  "You are the": "Sie sind",
  "You can add {0} more videos.": "Sie können noch {0} Videos hinzufügen.",
  "You can add {0} more — the limit is {1}.": "Sie können noch {0} hinzufügen — das Limit liegt bei {1}.",
  "You can enter a reference now. Confirm receipt unlocks only after the tenant reports the transfer as sent.": "Sie können jetzt eine Referenz eingeben. „Eingang bestätigen“ wird erst freigeschaltet, wenn der Mieter die Überweisung als gesendet meldet.",
  "You can publish this listing without these photos. You cannot accept a tenant without them — they are the record the deposit is settled against, so a letting with no move-in record has nothing to deduct from at the end.": "Sie können dieses Inserat ohne diese Fotos veröffentlichen. Einen Mieter können Sie ohne sie aber nicht annehmen — sie sind die Grundlage, auf der die Kaution abgerechnet wird. Eine Vermietung ohne Einzugsprotokoll bietet am Ende nichts, wovon abgezogen werden kann.",
  "You confirmed a receiving account earlier, so you can still list. Adding it above means a tenant can actually be shown where to pay you.": "Sie haben früher ein Empfangskonto bestätigt, daher können Sie weiterhin inserieren. Wenn Sie es oben hinzufügen, kann einem Mieter tatsächlich angezeigt werden, wohin er Sie bezahlen soll.",
  "You have asked to reopen it — waiting for the other party to agree.": "Sie haben um erneutes Öffnen gebeten — warten auf die Zustimmung der anderen Partei.",
  "You have not asked to view anywhere yet.": "Sie haben noch keine Besichtigung angefragt.",
