  "You may add your passport or ID now, which can improve your chance of approval. You may also wait: the host can pre-approve you, but final approval will remain pending until your ID is uploaded and reviewed.": "Sie können jetzt Ihren Reisepass oder Ausweis hinzufügen, was Ihre Chancen auf eine Zusage verbessern kann. Sie können auch warten: Der Gastgeber kann Sie vorab genehmigen, die endgültige Zusage bleibt aber offen, bis Ihr Ausweis hochgeladen und geprüft wurde.",
