  "You will hear from us when someone asks about a place, signs a contract, or answers your walkthrough photos.": "Sie hören von uns, wenn jemand nach einer Immobilie fragt, einen Vertrag unterschreibt oder auf Ihre Übergabefotos antwortet.",
  "Your ID could not be uploaded. Please try again.": "Ihr Ausweis konnte nicht hochgeladen werden. Bitte versuchen Sie es erneut.",
