  "Your link stays private. It is never on your profile and never in search — only a person with a real agreement with you can see it.": "Ihr Link bleibt privat. Er erscheint nie in Ihrem Profil und nie in der Suche — nur eine Person mit einer echten Vereinbarung mit Ihnen kann ihn sehen.",
  "Your listing loaded, but its private address did not. Reload before editing so it cannot be accidentally cleared.": "Ihr Inserat wurde geladen, die private Adresse jedoch nicht. Laden Sie vor dem Bearbeiten neu, damit sie nicht versehentlich gelöscht wird.",
  "Your listing will say you told us this, and that OneHome has not checked the policy. We will never call it verified, because we have not seen it.": "Ihr Inserat wird angeben, dass Sie uns dies mitgeteilt haben und dass OneHome die Police nicht geprüft hat. Wir werden sie nie als verifiziert bezeichnen, weil wir sie nicht gesehen haben.",
