  "Both of you agreed these {0} photos. Nobody can add, edit or remove one now — including us. This is the evidence any deposit question is settled against.": "Vocês dois aprovaram estas {0} fotos. Ninguém pode adicionar, editar ou remover nenhuma agora — nem nós. Esta é a prova com base na qual qualquer questão sobre o depósito é resolvida.",
