  "Cancelled. It stays active until the period you have already paid for ends.": "Cancelado. Ele continua ativo até o fim do período que você já pagou.",
  "Capped at the 28th so the date exists in every month — a rent due on the 30th silently skips February.": "Limitado ao dia 28 para que a data exista em todos os meses — um aluguel com vencimento no dia 30 pula fevereiro sem aviso.",
