  "Check in": "Fazer check-in",
  "Check in when you physically arrive. We time-stamp it, then unlock the private move-in photos for your review.": "Faça o check-in quando chegar fisicamente. Registramos o horário e liberamos as fotos privadas de entrada para sua revisão.",
  "Check out": "Fazer check-out",
  "Check out only after you have left the property. We time-stamp it and start the host's four-hour inspection window, which always ends before the next tenant checks in.": "Faça o check-out somente depois de sair do imóvel. Registramos o horário e iniciamos o prazo de inspeção de quatro horas do anfitrião, que sempre termina antes do check-in do próximo inquilino.",
