  "Choose the still that leads the listing, and the photo or video that leads your card in Discover.": "Escolha a imagem que abre o anúncio e a foto ou o vídeo que abre seu card no Discover.",
  "Choose…": "Escolher…",
  "Choosing the first day saves a private draft, so your viewing times are not lost.": "Escolher o primeiro dia salva um rascunho privado, para que seus horários de visita não se percam.",
