  "Collapse": "Recolher",
  "Colombia has no public record of it. Every listing here carries its registry chain.": "A Colômbia não tem registro público disso. Cada anúncio aqui traz sua cadeia de registros.",
  "Colombia has no public record of what a property last sold for. Every listing here starts one.": "A Colômbia não tem registro público do valor pelo qual um imóvel foi vendido pela última vez. Cada anúncio aqui começa um.",
  "Colombia has no public record of what anything rents for — leases are never registered. OneHome keeps its own from the day a listing appears, so this fills in as prices move.": "A Colômbia não tem registro público de quanto se paga de aluguel — contratos de locação nunca são registrados. A OneHome mantém o próprio registro desde o dia em que um anúncio aparece, então isto vai sendo preenchido conforme os preços mudam.",
  "Colombian law (Ley 820 de 2003, art. 16) restricts cash security deposits on residential leases, including when they are collected through an intermediary or called something else. A codeudor or a rent guarantee policy is what is normally used instead.": "A lei colombiana (Ley 820 de 2003, art. 16) restringe cauções em dinheiro em locações residenciais, inclusive quando cobradas por um intermediário ou com outro nome. Normalmente, usa-se um codeudor ou um seguro-fiança no lugar.",
  "Colombian law does not allow this on a home rental": "A lei colombiana não permite isso em locação residencial",
