  "Dates are not held until the host pre-approves. Do not send payment yet.": "As datas só ficam reservadas após a pré-aprovação do anfitrião. Não envie o pagamento ainda.",
  "Dates are not held yet. Pre-approval sends the tenant one request for their identity and payment. Choose how long they have to complete both.": "As datas ainda não estão reservadas. A pré-aprovação envia ao inquilino um único pedido de identidade e pagamento. Escolha quanto tempo ele tem para concluir os dois.",
  "Dates held · {0}h {1}m left to report payment. Deadline: {2}, Colombia time.": "Datas reservadas · {0} h {1} min restantes para informar o pagamento. Prazo: {2}, horário da Colômbia.",
  "Days after the agreed move-out. You return it, not us. Saying it up front is what stops the argument at the end.": "Dias após a saída combinada. Quem devolve é você, não nós. Deixar isso claro desde o início evita discussões no final.",
