  "Due each month on the": "Vence todo mês no dia",
  "E.g. software engineer working remotely, moving from Chicago, quiet, no smoking, looking for somewhere for at least a year in Laureles.": "Ex.: engenheiro de software em trabalho remoto, vindo de Chicago, tranquilo, não fumante, procurando um lugar por pelo menos um ano em Laureles.",
  "E.g. three bedrooms, 120 square metres, eighth floor with a balcony, renovated kitchen, two parking spaces, estrato 5, building from 2015.": "Ex.: três quartos, 120 metros quadrados, oitavo andar com varanda, cozinha reformada, duas vagas de garagem, estrato 5, prédio de 2015.",
  "E.g. two bedrooms, tenth floor, morning light, quiet street, five minutes' walk to Parque Lleras, building has a gym and 24-hour porter.": "Ex.: dois quartos, décimo andar, sol da manhã, rua tranquila, cinco minutos a pé do Parque Lleras, prédio com academia e portaria 24 horas.",
  "Each missing detail must be completed where it is managed. The agreement stays in draft until all required details are available.": "Cada dado ausente deve ser completado onde é gerenciado. O contrato fica em rascunho até que todos os dados obrigatórios estejam disponíveis.",
