  "Event sharing is coming soon": "Compartilhar eventos chega em breve",
  "Every agent here carries a OneScore built from work they have actually completed — across renting, jobs and events. It is the part a WhatsApp group cannot give you.": "Cada corretor aqui tem um OneScore construído com trabalhos que realmente concluiu — em aluguéis, serviços e eventos. É o que um grupo de WhatsApp não pode lhe dar.",
  "Every agent here carries a OneScore built from work they have actually completed — across selling, renting, jobs and events. It is the part a WhatsApp group cannot give you.": "Todo corretor aqui tem um OneScore construído a partir de trabalhos que realmente concluiu — em vendas, aluguéis, serviços e eventos. É o que um grupo de WhatsApp não pode oferecer.",
  "Every lease and sale agreement you sign lands here, ready to share or print.": "Todo contrato de locação e de compra e venda que você assinar aparece aqui, pronto para compartilhar ou imprimir.",
  "Every lease and sale agreement you've signed — share, save or print.": "Todos os contratos de aluguel e de compra e venda que você assinou — compartilhe, salve ou imprima.",
  "Every price shown is per month.": "Todos os preços mostrados são por mês.",
  "Every price shown is per night.": "Todos os preços mostrados são por noite.",
  "Every registered sale on this folio — what it actually changed hands for, the deed number and the notaría — is pulled from the national registry and shown on your listing. Nobody else in Colombia puts that in front of a buyer.": "Cada venda registrada neste folio — o valor real da negociação, o número da escritura e a notaría — é obtida do registro nacional e exibida no seu anúncio. Ninguém mais na Colômbia mostra isso a um comprador.",
  "Everything above is exactly what a buyer will see.": "Tudo acima é exatamente o que o comprador verá.",
  "Everything above is exactly what a tenant will see.": "Tudo acima é exatamente o que um inquilino verá.",
  "Everything you have listed, to let and to sell. Tap any one to open its listing.": "Tudo o que você anunciou, para alugar e vender. Toque em qualquer um para abrir o anúncio.",
  "Everything you've hearted, rent and sale together.": "Tudo o que você curtiu, aluguel e venda juntos.",
  "Everything you've hearted, sale and rent together.": "Tudo o que você curtiu, venda e aluguel juntos.",
  "Excellent": "Excelente",
  "Existing stay: August 29 onward is available. For September rent, select September 1 and October 1 (checkout). August proration is separate.": "Estadia existente: disponível a partir de 29 de agosto. Para o aluguel de setembro, selecione 1º de setembro e 1º de outubro (saída). O valor proporcional de agosto é separado.",
  "Expired": "Expirado",
  "Fair": "Regular",
  "Families search on this before anything else.": "É a primeira coisa que as famílias procuram.",
