  "Fill them in": "Preencher",
  "Fill this in once. Every place you enquire about gets a complete application instead of a message asking if it's still available — which is how you get answered first.": "Preencha uma vez. Cada imóvel sobre o qual você perguntar recebe uma candidatura completa, em vez de uma mensagem perguntando se ainda está disponível — é assim que você é respondido primeiro.",
