  "Held until the closing date, up to six months. Every movement is timestamped and both sides see it.": "Retido até a data de fechamento, por até seis meses. Cada movimentação tem registro de data e hora, e ambas as partes podem ver.",
  "Help requests open 24 hours after reporting an external payment, while receipt remains unconfirmed.": "Os pedidos de ajuda ficam disponíveis 24 horas após o registro de um pagamento externo, enquanto o recebimento não for confirmado.",
