  "I agree these photos are accurate": "Concordo que estas fotos estão corretas",
  "I agree to receive reservation texts at my verified phone. Message and data rates may apply. Turn this off here at any time.": "Concordo em receber SMS sobre reservas no meu telefone verificado. Podem ser cobradas tarifas de mensagens e dados. Desative aqui a qualquer momento.",
  "I agree to sign this agreement electronically.": "Concordo em assinar este contrato eletronicamente.",
  "I am authorized to offer this property and everything in this listing is accurate.": "Estou autorizado a oferecer este imóvel e todas as informações deste anúncio são verdadeiras.",
  "I am coming with my partner.": "Vou com meu parceiro.",
  "I am the owner of this property, or authorised by the owner to offer it for sale, and everything in this listing is accurate.": "Sou o proprietário deste imóvel ou estou autorizado pelo proprietário a colocá-lo à venda, e todas as informações deste anúncio são verdadeiras.",
  "I can get a rent guarantee policy": "Posso contratar um seguro-fiança",
  "I can move in from": "Posso me mudar a partir de",
  "I have a co-signer (codeudor)": "Tenho um fiador (codeudor)",
