  "I understand": "Entendi",
  "I understand: these clauses are optional. Tap a card to add it, and tap it again to remove it.": "Entendi: estas cláusulas são opcionais. Toque em um cartão para adicioná-lo e toque de novo para removê-lo.",
  "Identity": "Identidade",
  "Identity checked by OneHome": "Identidade verificada pela OneHome",
  "Identity is linked from the tenant's One ID. Adjust only the dates or terms if you are making a special offer.": "A identidade vem do One ID do inquilino. Ajuste apenas as datas ou condições se estiver fazendo uma oferta especial.",
  "Identity review is still required before final approval.": "A revisão de identidade ainda é necessária antes da aprovação final.",
  "If the problem cannot be seen — the air conditioner is not blowing cold air — photograph it anyway and say so here. A caption is what turns a photo into evidence.": "Se o problema não aparece — o ar-condicionado não está gelando — fotografe mesmo assim e explique aqui. É a legenda que transforma uma foto em prova.",
  "If the window closes with photos that were never answered, the photos stand as the record and the silence is recorded with them. If nobody submitted anything, there is no move-in record — and with no record, nothing can be deducted from the deposit at the end.": "Se o prazo terminar com fotos sem resposta, as fotos valem como registro e o silêncio fica registrado junto. Se ninguém enviou nada, não há registro de entrada — e, sem registro, nada pode ser descontado do depósito no final.",
  "If they move in mid-month, the part-month at the start.": "Se a mudança for no meio do mês, a fração do mês no início.",
  "If you both agree, it can reopen once for another 48 hours.": "Se os dois concordarem, ele pode ser reaberto uma vez por mais 48 horas.",
  "If you opened the link in the same email, the code was already used — they are one and the same. Send a fresh one and type it without opening the link.": "Se você abriu o link no mesmo e-mail, o código já foi usado — os dois são a mesma coisa. Peça um novo e digite-o sem abrir o link.",
  "Important information about Colombian deposit law": "Informações importantes sobre a lei colombiana de cauções",
  "In the building": "No prédio",
  "In your comparison": "Na sua comparação",
  "Include my own terms or contract? (optional)": "Incluir meus próprios termos ou contrato? (opcional)",
  "Included with every account": "Incluído em todas as contas",
  "Includes a {0} guest service fee.": "Inclui uma taxa de serviço do hóspede de {0}.",
  "Instagram doesn't show links in posts, so it gets a picture with the link printed on it — and the link is copied for the Link sticker.": "O Instagram não mostra links nas publicações, então ele recebe uma imagem com o link impresso — e o link é copiado para o sticker de link.",
  "Introduce me": "Quero uma indicação",
