  "Let the public comment on this listing": "Permitir comentários públicos neste anúncio",
  "Ley 820 de 2003 (Article 16) says a landlord may not require a cash deposit on a residential lease of 30 days or more. A tenant can ask for it back at any time and the clause has no force. OneHome does not collect it, hold it, or return it, and takes no fee on it — it is paid to you directly and it is between you and the tenant. The tenant is told all of this on your listing.": "A Ley 820 de 2003 (artigo 16) determina que o locador não pode exigir caução em dinheiro em locação residencial de 30 dias ou mais. O inquilino pode pedir a devolução a qualquer momento, e a cláusula não tem validade. A OneHome não cobra, não guarda nem devolve esse valor, e não cobra taxa sobre ele — ele é pago diretamente a você e é um assunto entre você e o inquilino. O inquilino é informado de tudo isso no seu anúncio.",
