  "No bed": "Sem cama",
  "No cash changes hands to secure the lease — which is the arrangement Colombian residential law is built around.": "Nenhum dinheiro troca de mãos para garantir a locação — que é o modelo em torno do qual a lei residencial colombiana foi construída.",
