  "Similar units in {0}": "Unidades semelhantes em {0}",
  "Single": "Solteiro",
  "Size & rooms": "Tamanho e cômodos",
  "Size (min m²)": "Área (mín. m²)",
  "Sleeps at least": "Acomoda pelo menos",
  "Sleeps {0}+": "Acomoda {0}+",
