  "Sold furnished": "Vendido mobiliado",
  "Some of those nights are taken": "Algumas dessas noites estão ocupadas",
  "Somebody could book a viewing for later today.": "Alguém poderia agendar uma visita para mais tarde hoje.",
  "Somebody just took that time. Here are the times still free.": "Alguém acabou de pegar esse horário. Aqui estão os horários ainda livres.",
  "Someone in Colombia who'll guarantee the lease.": "Alguém na Colômbia que vai garantir o contrato.",
  "Someone is always there": "Sempre tem alguém",
  "Something is wrong": "Algo está errado",
  "Something on OneHome still points at this place - usually a contract - so it cannot be deleted. That link is what keeps those records readable for everyone on them. Archive it instead: it leaves your working list and public search, and every record stays intact.": "Algo no OneHome ainda aponta para este imóvel - geralmente um contrato - por isso ele não pode ser excluído. Esse vínculo mantém os registros legíveis para todos os envolvidos. Arquive-o em vez disso: ele sai da sua lista de trabalho e da busca pública, e todos os registros permanecem intactos.",
  "Sort": "Ordenar",
  "Sort by": "Ordenar por",
  "Source: IGAC / national property registry, open data · matrícula ": "Fonte: IGAC / registro nacional de imóveis, dados abertos · matrícula ",
  "Split equally": "Dividida igualmente",
  "Standard lease terms for this property": "Termos padrão de locação deste imóvel",
  "Start a different listing": "Começar outro anúncio",
  "Start the walkthrough": "Iniciar a vistoria",
  "Starts": "Início",
  "Stay until {0} instead of {1}.": "Fique até {0} em vez de {1}.",
  "Stays under 30 nights are lodging, not a home lease, so a card hold is the right instrument and the only one offered here.": "Estadias de menos de 30 noites são hospedagem, não locação residencial, por isso a pré-autorização no cartão é o instrumento adequado e o único oferecido aqui.",
  "Still building it": "Ainda construindo",
  "Still needed:": "Ainda falta:",
