  "3-bedroom apartment in Laureles": "Квартира с 3 спальнями в Laureles",
  "5,000 characters": "5 000 символов",
  "50 rules": "50 правил",
  "A band, not a score — we don't check it and we don't pretend to.": "Это диапазон, а не балл — мы его не проверяем и не делаем вид, что проверяем.",
  "A cash security deposit": "Денежный залог",
  "A co-signer (codeudor)": "Поручитель (codeudor)",
  "A flat charge for one stay, paid to you with the rent. Leave it empty if you charge none.": "Фиксированная сумма за одно проживание, выплачивается вам вместе с арендной платой. Оставьте пустым, если не взимаете её.",
  "A help request does not confirm payment, change your reservation or guarantee recovery of an external transfer.": "Запрос помощи не подтверждает оплату, не меняет бронирование и не гарантирует возврат внешнего перевода.",
  "A lease. Billed on the same date each calendar month — never in 30-day blocks.": "Аренда. Оплата в одно и то же число каждого календарного месяца — никогда не блоками по 30 дней.",
  "A line about you": "Пара слов о себе",
  "A listing": "Объявление",
  "A name and one way to reach you is the whole requirement. Everything else is yours to add when you want to.": "Нужны только имя и один способ связи. Всё остальное можно добавить, когда захотите.",
  "A note about it": "Примечание",
  "A private one-hour viewing link was copied.": "Скопирована закрытая ссылка для просмотра, действующая один час.",
  "A rent guarantee policy": "Полис гарантии арендной платы",
  "A seguro de arrendamiento from an insurer — the usual alternative to a deposit here.": "Seguro de arrendamiento от страховой компании — обычная здесь альтернатива залогу.",
  "A short introduction": "Краткое представление",
  "A starting point, not legal advice. It follows the {0} sections a Colombian residential lease normally carries — term, IPC increase, repairs, the acta de entrega, default — in our own words, and a Colombian attorney has not reviewed it yet.": "Это отправная точка, а не юридическая консультация. Своими словами он повторяет типовые разделы колумбийского договора аренды жилья (всего {0}) — срок, индексация по IPC, ремонт, acta de entrega, просрочка, — и колумбийский юрист его ещё не проверял.",
  "A stay. Billed once for the whole booking.": "Проживание. Оплата один раз за всё бронирование.",
  "A way to get paid when a card won't work. The other person pays you straight through {0} — the money never comes to {1}, so ": "Способ получить оплату, если карта не работает. Другой человек платит вам напрямую через {0} — деньги никогда не поступают в {1}, поэтому ",
  "A {0}-day window gives the landlord or manager {1} day{2} to submit photos, then leaves {3} day{4} for the tenant.": "Окно в {0} дн. даёт арендодателю или управляющему {1} дн.{2} на загрузку фото, затем остаётся {3} дн.{4} арендатору.",
