  "Both of you agreed these {0} photos. Nobody can add, edit or remove one now — including us. This is the evidence any deposit question is settled against.": "Вы оба согласовали эти фото ({0}). Теперь никто не может добавить, изменить или удалить ни одно из них — даже мы. Именно по ним решается любой вопрос о депозите.",
  "Both of you hold the same copy. If a single character ever differed, this fingerprint would not match.": "У вас обоих одна и та же копия. Если бы отличался хотя бы один символ, этот отпечаток не совпал бы.",
