  "Cancelled. It stays active until the period you have already paid for ends.": "Отменено. Тариф действует до конца уже оплаченного периода.",
  "Capped at the 28th so the date exists in every month — a rent due on the 30th silently skips February.": "Не позднее 28-го числа, чтобы такая дата была в каждом месяце — срок 30-го числа незаметно пропускает февраль.",
