  "Change this request only": "Изменить только эту заявку",
  "Changes here apply only to this request. The public listing stays unchanged.": "Изменения здесь касаются только этой заявки. Публичное объявление останется прежним.",
  "Check dates": "Проверить даты",
  "Check in": "Заселиться",
  "Check in when you physically arrive. We time-stamp it, then unlock the private move-in photos for your review.": "Отметьте заселение, когда физически прибудете на место. Мы зафиксируем время и откроем закрытые фото заселения для проверки.",
  "Check out": "Выехать",
  "Check out only after you have left the property. We time-stamp it and start the host's four-hour inspection window, which always ends before the next tenant checks in.": "Отмечайте выезд только после того, как покинете объект. Мы зафиксируем время и запустим четырёхчасовое окно осмотра для хозяина, которое всегда заканчивается до заселения следующего арендатора.",
  "Check this one with your lawyer": "Уточните это у своего юриста",
