  "Choose the still that leads the listing, and the photo or video that leads your card in Discover.": "Выберите кадр, с которого начинается объявление, и фото или видео, с которого начинается ваша карточка в Discover.",
  "Choose…": "Выберите…",
  "Choosing the first day saves a private draft, so your viewing times are not lost.": "Выбор первого дня сохраняет личный черновик, чтобы ваше время для просмотров не потерялось.",
  "Circles are approximate — the exact address stays private until there's a contract.": "Круги приблизительные — точный адрес скрыт до заключения договора.",
  "Cleaning fee": "Плата за уборку",
  "Clear": "Очистить",
