  "Close request": "Закрыть запрос",
  "Closing at the notary": "Закрытие сделки у нотариуса",
  "Collapse": "Свернуть",
  "Colombia has no public record of it. Every listing here carries its registry chain.": "В Колумбии нет публичных данных об этом. Каждое объявление здесь содержит свою цепочку записей из реестра.",
  "Colombia has no public record of what a property last sold for. Every listing here starts one.": "В Колумбии нет публичных данных о том, за сколько объект был продан в последний раз. Каждое объявление здесь начинает такую историю.",
  "Colombia has no public record of what anything rents for — leases are never registered. OneHome keeps its own from the day a listing appears, so this fills in as prices move.": "В Колумбии нет публичных данных о том, сколько стоит аренда, — договоры аренды никогда не регистрируются. OneHome ведёт собственный учёт с того дня, как появляется объявление, поэтому этот раздел заполняется по мере изменения цен.",
  "Colombian law (Ley 820 de 2003, art. 16) restricts cash security deposits on residential leases, including when they are collected through an intermediary or called something else. A codeudor or a rent guarantee policy is what is normally used instead.": "Колумбийское законодательство (Ley 820 de 2003, ст. 16) ограничивает денежные залоги по договорам аренды жилья, в том числе если их взимает посредник или они называются иначе. Вместо этого обычно используют codeudor или полис гарантии арендной платы.",
  "Colombian law does not allow this on a home rental": "Колумбийское законодательство не допускает этого при аренде жилья",
  "Coming soon": "Скоро",
