  "Complete these steps before sending the lease:": "Выполните эти шаги перед отправкой договора:",
  "Complete this on the listing.": "Заполните это в объявлении.",
  "Complete this once before listing. OneHome uses it to prepare private rental documents, so you do not retype the same owner or manager details for every tenant.": "Заполните это один раз перед размещением. OneHome использует эти данные для подготовки закрытых документов аренды, чтобы вам не вводить одни и те же сведения о собственнике или управляющем для каждого арендатора.",
  "Complete this once before you list a property.": "Заполните один раз перед размещением объекта.",
