  "Dates are not held until the host pre-approves. Do not send payment yet.": "Даты не закреплены до предварительного одобрения хозяином. Пока не отправляйте оплату.",
  "Dates are not held yet. Pre-approval sends the tenant one request for their identity and payment. Choose how long they have to complete both.": "Даты ещё не забронированы. Предварительное одобрение отправит арендатору один запрос на документы и оплату. Выберите, сколько времени у него будет на оба шага.",
  "Dates held · {0}h {1}m left to report payment. Deadline: {2}, Colombia time.": "Даты забронированы · осталось {0} ч {1} мин, чтобы сообщить об оплате. Срок: {2}, по времени Колумбии.",
  "Days after the agreed move-out. You return it, not us. Saying it up front is what stops the argument at the end.": "Дней после согласованного выезда. Возвращаете его вы, а не мы. Если сказать об этом заранее, в конце не будет споров.",
