  "Due each month on the": "Оплата ежемесячно, число",
  "E.g. software engineer working remotely, moving from Chicago, quiet, no smoking, looking for somewhere for at least a year in Laureles.": "Например: инженер-программист на удалёнке, переезжаю из Чикаго, спокойный, не курю, ищу жильё минимум на год в Laureles.",
  "E.g. three bedrooms, 120 square metres, eighth floor with a balcony, renovated kitchen, two parking spaces, estrato 5, building from 2015.": "Например: три спальни, 120 квадратных метров, восьмой этаж с балконом, отремонтированная кухня, два парковочных места, estrato 5, дом 2015 года.",
  "E.g. two bedrooms, tenth floor, morning light, quiet street, five minutes' walk to Parque Lleras, building has a gym and 24-hour porter.": "Например: две спальни, десятый этаж, утреннее солнце, тихая улица, пять минут пешком до Parque Lleras, в доме есть спортзал и круглосуточный консьерж.",
  "Each missing detail must be completed where it is managed. The agreement stays in draft until all required details are available.": "Каждое недостающее поле нужно заполнить там, где оно ведётся. Договор остаётся черновиком, пока не будут готовы все обязательные сведения.",
  "Each person signs from their own account, using this email.": "Каждый подписывает из своего аккаунта, используя этот адрес эл. почты.",
  "Earnest money": "Задаток",
