  "Event sharing is coming soon": "Отправка мероприятий скоро появится",
  "Every agent here carries a OneScore built from work they have actually completed — across renting, jobs and events. It is the part a WhatsApp group cannot give you.": "У каждого агента здесь есть OneScore, основанный на реально выполненной работе — в аренде, заказах и мероприятиях. Именно этого не даст ни одна группа в WhatsApp.",
  "Every agent here carries a OneScore built from work they have actually completed — across selling, renting, jobs and events. It is the part a WhatsApp group cannot give you.": "У каждого агента здесь есть OneScore, основанный на реально выполненной работе — продажи, аренда, заказы и мероприятия. Этого не даст ни одна группа в WhatsApp.",
  "Every lease and sale agreement you sign lands here, ready to share or print.": "Все подписанные вами договоры аренды и купли-продажи появляются здесь — их можно отправить или распечатать.",
  "Every lease and sale agreement you've signed — share, save or print.": "Все подписанные вами договоры аренды и купли-продажи — делитесь, сохраняйте или печатайте.",
  "Every price shown is per month.": "Все цены указаны за месяц.",
  "Every price shown is per night.": "Все цены указаны за ночь.",
  "Every registered sale on this folio — what it actually changed hands for, the deed number and the notaría — is pulled from the national registry and shown on your listing. Nobody else in Colombia puts that in front of a buyer.": "Каждая зарегистрированная продажа по этому folio — реальная цена сделки, номер нотариального акта и нотариальная контора — загружается из национального реестра и отображается в вашем объявлении. Больше никто в Колумбии не показывает это покупателю.",
  "Everything above is exactly what a buyer will see.": "Всё, что выше, покупатель увидит именно так.",
  "Everything above is exactly what a tenant will see.": "Всё, что выше, арендатор увидит именно так.",
  "Everything you have listed, to let and to sell. Tap any one to open its listing.": "Всё, что вы разместили, — в аренду и на продажу. Нажмите на любой объект, чтобы открыть объявление.",
  "Everything you've hearted, rent and sale together.": "Всё, что вы отметили сердечком, — аренда и продажа вместе.",
  "Everything you've hearted, sale and rent together.": "Всё, что вы отметили сердечком, — продажа и аренда вместе.",
  "Excellent": "Отличная",
  "Existing stay: August 29 onward is available. For September rent, select September 1 and October 1 (checkout). August proration is separate.": "Текущее проживание: свободно с 29 августа. Для оплаты за сентябрь выберите 1 сентября и 1 октября (выезд). Пропорциональная оплата за август — отдельно.",
  "Expired": "Истёк",
  "Fair": "Средняя",
  "Families search on this before anything else.": "Семьи ищут это в первую очередь.",
  "Fill in this addendum": "Заполнить это дополнение",
