  "Fill them in": "Заполнить",
  "Fill this in once. Every place you enquire about gets a complete application instead of a message asking if it's still available — which is how you get answered first.": "Заполните один раз. По каждому интересующему вас объекту будет отправлена полная анкета, а не сообщение «Ещё актуально?» — так вам ответят первым.",
