  "Has a co-signer (codeudor) in Colombia": "Есть поручитель (codeudor) в Колумбии",
  "Held until the closing date, up to six months. Every movement is timestamped and both sides see it.": "Хранится до даты закрытия сделки, не более шести месяцев. Каждое движение средств фиксируется по времени и видно обеим сторонам.",
  "Help requests open 24 hours after reporting an external payment, while receipt remains unconfirmed.": "Запросить помощь можно через 24 часа после сообщения о внешнем платеже, пока получение не подтверждено.",
  "Hi — is \"{0}\" still for sale?": "Здравствуйте — «{0}» ещё продаётся?",
