  "How to reach you": "Как с вами связаться",
  "How would you like to pay?": "Как вы хотите оплатить?",
  "I agree these photos are accurate": "Я подтверждаю, что эти фото достоверны",
  "I agree to receive reservation texts at my verified phone. Message and data rates may apply. Turn this off here at any time.": "Я согласен получать SMS о бронировании на подтверждённый номер телефона. Может взиматься плата за сообщения и передачу данных. Отключить можно здесь в любое время.",
  "I agree to sign this agreement electronically.": "Я соглашаюсь подписать этот договор в электронном виде.",
  "I am authorized to offer this property and everything in this listing is accurate.": "Я уполномочен предлагать этот объект, и все сведения в объявлении достоверны.",
  "I am coming with my partner.": "Я приду с партнёром.",
  "I am the owner of this property, or authorised by the owner to offer it for sale, and everything in this listing is accurate.": "Я являюсь владельцем этого объекта или уполномочен владельцем выставить его на продажу, и все сведения в этом объявлении достоверны.",
  "I can get a rent guarantee policy": "Я могу оформить страховку гарантии аренды",
  "I can move in from": "Могу заселиться с",
  "I have a co-signer (codeudor)": "У меня есть поручитель (codeudor)",
  "I have pets": "У меня есть питомцы",
  "I understand": "Понятно",
  "I understand: these clauses are optional. Tap a card to add it, and tap it again to remove it.": "Понятно: эти пункты необязательны. Нажмите на карточку, чтобы добавить её, и ещё раз, чтобы убрать.",
  "Identity": "Личность",
  "Identity checked by OneHome": "Личность проверена OneHome",
  "Identity is linked from the tenant's One ID. Adjust only the dates or terms if you are making a special offer.": "Личность подтягивается из One ID арендатора. Меняйте только даты или условия, если делаете особое предложение.",
  "Identity review is still required before final approval.": "Перед окончательным одобрением ещё нужна проверка личности.",
  "If the problem cannot be seen — the air conditioner is not blowing cold air — photograph it anyway and say so here. A caption is what turns a photo into evidence.": "Если проблему не видно — кондиционер не охлаждает, — всё равно сфотографируйте и укажите это здесь. Именно подпись превращает фото в доказательство.",
  "If the window closes with photos that were never answered, the photos stand as the record and the silence is recorded with them. If nobody submitted anything, there is no move-in record — and with no record, nothing can be deducted from the deposit at the end.": "Если срок истёк, а на фото так и не ответили, фото становятся документом, а молчание фиксируется вместе с ними. Если никто ничего не загрузил, акта заселения нет — а без него в конце ничего нельзя удержать из депозита.",
  "If they move in mid-month, the part-month at the start.": "Если заселение в середине месяца — оплата за неполный первый месяц.",
  "If you both agree, it can reopen once for another 48 hours.": "Если вы оба согласны, его можно один раз открыть ещё на 48 часов.",
  "If you opened the link in the same email, the code was already used — they are one and the same. Send a fresh one and type it without opening the link.": "Если вы открыли ссылку из того же письма, код уже использован — это одно и то же. Запросите новый и введите его, не открывая ссылку.",
  "Important information about Colombian deposit law": "Важная информация о колумбийском законе о залогах",
  "In the building": "В здании",
  "In your comparison": "В вашем сравнении",
  "Include my own terms or contract? (optional)": "Добавить свои условия или договор? (необязательно)",
  "Included with every account": "Входит в каждый аккаунт",
  "Includes a {0} guest service fee.": "Включает сервисный сбор для гостя: {0}.",
  "Instagram doesn't show links in posts, so it gets a picture with the link printed on it — and the link is copied for the Link sticker.": "Instagram не показывает ссылки в публикациях, поэтому туда уходит картинка с напечатанной ссылкой — а сама ссылка копируется для стикера «Ссылка».",
  "Introduce me": "Познакомьте меня",
  "It happened": "Состоялся",
  "It may have been deleted, or it belongs to someone else.": "Возможно, она удалена или принадлежит другому человеку.",
  "It may have been turned off or replaced. Ask them to show you a current one.": "Возможно, его отключили или заменили. Попросите показать актуальный код.",
  "It will read": "Будет указано",
  "It's on the top of the certificado de tradición y libertad, and it looks like 001-1234567.": "Он указан в верхней части certificado de tradición y libertad и выглядит так: 001-1234567.",
  "Jacuzzi": "Джакузи",
