  "Leave on": "Выезд",
  "Leave without saving": "Выйти без сохранения",
  "Leave without saving? Anything you have typed here will be lost.": "Выйти без сохранения? Всё, что вы здесь ввели, будет потеряно.",
  "Leaves the draft above untouched.": "Черновик выше останется без изменений.",
  "Let me share this with a code or link": "Разрешить делиться по коду или ссылке",
  "Let people book a viewing": "Разрешить бронировать просмотр",
  "Let the public comment on this listing": "Разрешить публичные комментарии к объявлению",
  "Ley 820 de 2003 (Article 16) says a landlord may not require a cash deposit on a residential lease of 30 days or more. A tenant can ask for it back at any time and the clause has no force. OneHome does not collect it, hold it, or return it, and takes no fee on it — it is paid to you directly and it is between you and the tenant. The tenant is told all of this on your listing.": "Ley 820 de 2003 (статья 16) устанавливает, что арендодатель не может требовать денежный залог по договору аренды жилья на 30 дней и более. Арендатор вправе в любой момент потребовать его возврата, а такое условие не имеет силы. OneHome не взимает, не хранит и не возвращает его и не берёт с него комиссию — он выплачивается вам напрямую, и это вопрос между вами и арендатором. Арендатор увидит всю эту информацию в вашем объявлении.",
  "Like": "Нравится",
  "Link copied": "Ссылка скопирована",
