  "No OneHome fee on this letting. You receive the full rent.": "Без комиссии OneHome за эту аренду. Вы получаете полную сумму.",
  "No OneHome service fee on this request, for you or the host.": "За этот запрос OneHome не берёт сервисный сбор ни с вас, ни с хозяина.",
