  "Payments open shortly. Nothing has been charged, and this lease has not started — the dates are not committed to you yet.": "Оплата скоро станет доступна. Ничего не списано, и аренда ещё не началась — даты пока не закреплены за вами.",
  "Payouts arrive in about {0} days the first time, then about {1} days.": "Первая выплата приходит примерно за {0} дн., последующие — примерно за {1} дн.",
