  "Pesos converted at the official TRM in force {0} ({1} COP/USD), certified by the Superintendencia Financiera.": "Песо пересчитаны по официальному курсу TRM, действующему с {0} ({1} COP/USD), утверждённому Superintendencia Financiera.",
  "Pesos use the official TRM certified by the Superintendencia Financiera. Other currencies use the daily published rate.": "Для песо используется официальный курс TRM, утверждаемый Superintendencia Financiera. Для других валют — ежедневно публикуемый курс.",
