  "Check in": "办理入住",
  "Check in when you physically arrive. We time-stamp it, then unlock the private move-in photos for your review.": "请在实际到达后办理入住。我们会记录时间，然后解锁私人入住照片供您核对。",
  "Check out": "办理退房",
  "Check out only after you have left the property. We time-stamp it and start the host's four-hour inspection window, which always ends before the next tenant checks in.": "请在离开房屋后再办理退房。我们会记录时间，并开始房东的四小时检查期，该期限总会在下一位租客入住前结束。",
