  "Choose…": "请选择…",
  "Choosing the first day saves a private draft, so your viewing times are not lost.": "选择第一天时会保存一份私密草稿，以免您的看房时间丢失。",
  "Circles are approximate — the exact address stays private until there's a contract.": "圆圈仅为大致范围——签订合同前，确切地址保密。",
