  "Collapse": "收起",
  "Colombia has no public record of it. Every listing here carries its registry chain.": "哥伦比亚没有这方面的公开记录。这里的每个房源都附有其登记链。",
  "Colombia has no public record of what a property last sold for. Every listing here starts one.": "哥伦比亚没有公开记录房产上次的成交价。这里的每个房源都会开启一份记录。",
  "Colombia has no public record of what anything rents for — leases are never registered. OneHome keeps its own from the day a listing appears, so this fills in as prices move.": "哥伦比亚没有任何公开的租金记录——租约从不登记。OneHome 从房源上线之日起自行记录，因此随着价格变动，这里会逐步完善。",
  "Colombian law (Ley 820 de 2003, art. 16) restricts cash security deposits on residential leases, including when they are collected through an intermediary or called something else. A codeudor or a rent guarantee policy is what is normally used instead.": "哥伦比亚法律（Ley 820 de 2003，第 16 条）限制住宅租约收取现金押金，包括通过中介收取或以其他名义收取的情况。通常改用 codeudor（共同担保人）或租金担保保险。",
  "Colombian law does not allow this on a home rental": "哥伦比亚法律不允许住宅租赁收取此项",
  "Coming soon": "即将推出",
