  "Complete this once before listing. OneHome uses it to prepare private rental documents, so you do not retype the same owner or manager details for every tenant.": "发布房源前请完成一次。OneHome 会用它来准备私密租赁文件，这样你无需为每位租客重复填写相同的业主或管理人信息。",
