  "Dates are not held until the host pre-approves. Do not send payment yet.": "房东预批准前不会保留日期。请暂勿付款。",
  "Dates are not held yet. Pre-approval sends the tenant one request for their identity and payment. Choose how long they have to complete both.": "日期尚未保留。预批准会向租客发送一个同时要求身份信息和付款的请求。请选择其完成两项的期限。",
  "Dates held · {0}h {1}m left to report payment. Deadline: {2}, Colombia time.": "日期已保留 · 还剩 {0} 小时 {1} 分钟报告付款。截止时间：哥伦比亚时间 {2}。",
  "Days after the agreed move-out. You return it, not us. Saying it up front is what stops the argument at the end.": "约定退租后的天数。由你退还，而非我们。提前说明，才能避免最后的争执。",
