  "Due each month on the": "每月付款日",
  "E.g. software engineer working remotely, moving from Chicago, quiet, no smoking, looking for somewhere for at least a year in Laureles.": "例如：远程工作的软件工程师，从芝加哥搬来，安静，不吸烟，想在 Laureles 找住处，至少住一年。",
  "E.g. three bedrooms, 120 square metres, eighth floor with a balcony, renovated kitchen, two parking spaces, estrato 5, building from 2015.": "例如：三间卧室，120 平方米，八楼带阳台，厨房已翻新，两个车位，estrato 5，2015 年建成。",
  "E.g. two bedrooms, tenth floor, morning light, quiet street, five minutes' walk to Parque Lleras, building has a gym and 24-hour porter.": "例如：两间卧室，十楼，早晨采光好，街道安静，步行五分钟到 Parque Lleras，楼内有健身房和 24 小时门卫。",
  "Each missing detail must be completed where it is managed. The agreement stays in draft until all required details are available.": "每项缺失信息都必须在其所在位置补全。在所有必填信息齐全之前，协议将保持草稿状态。",
  "Each person signs from their own account, using this email.": "每个人都使用此邮箱，从自己的账户签署。",
