  "Event sharing is coming soon": "活动分享即将推出",
  "Every agent here carries a OneScore built from work they have actually completed — across renting, jobs and events. It is the part a WhatsApp group cannot give you.": "这里的每位经纪人都有基于其实际完成工作的 OneScore——涵盖租房、零工和活动。这是 WhatsApp 群组无法给您的。",
  "Every agent here carries a OneScore built from work they have actually completed — across selling, renting, jobs and events. It is the part a WhatsApp group cannot give you.": "这里的每位经纪人都有 OneScore，它基于其真实完成的工作 — 涵盖买卖、租赁、工作和活动。这是 WhatsApp 群无法给您的。",
  "Every lease and sale agreement you sign lands here, ready to share or print.": "你签署的每份租约和买卖协议都会出现在这里，可随时分享或打印。",
  "Every lease and sale agreement you've signed — share, save or print.": "您签署的所有租约和买卖协议 — 可分享、保存或打印。",
  "Every price shown is per month.": "所有显示价格均为每月价格。",
  "Every price shown is per night.": "所有显示价格均为每晚价格。",
  "Every registered sale on this folio — what it actually changed hands for, the deed number and the notaría — is pulled from the national registry and shown on your listing. Nobody else in Colombia puts that in front of a buyer.": "该 folio 上的每一笔登记交易 — 实际成交价、契据编号和公证处 — 都会从国家登记系统中调取并显示在您的房源中。哥伦比亚没有其他人向买家展示这些信息。",
  "Everything above is exactly what a buyer will see.": "以上内容就是买家将看到的样子。",
  "Everything above is exactly what a tenant will see.": "以上内容就是租客将看到的样子。",
  "Everything you have listed, to let and to sell. Tap any one to open its listing.": "您发布的所有出租和出售房源。点按任一项即可打开房源。",
  "Everything you've hearted, rent and sale together.": "你点过爱心的所有房源，出租和出售都在一起。",
  "Everything you've hearted, sale and rent together.": "您点过爱心的所有房源，出售和出租都在这里。",
  "Excellent": "优秀",
  "Existing stay: August 29 onward is available. For September rent, select September 1 and October 1 (checkout). August proration is separate.": "现有入住：8月29日起可租。如需支付9月租金，请选择9月1日和10月1日（退房）。8月按比例计算的租金另行处理。",
  "Expired": "已过期",
