  "I agree to receive reservation texts at my verified phone. Message and data rates may apply. Turn this off here at any time.": "我同意通过已验证的手机号接收预订短信。可能产生短信和流量费用。可随时在此关闭。",
  "I agree to sign this agreement electronically.": "我同意以电子方式签署本协议。",
