  "I am coming with my partner.": "我会和伴侣一起来。",
  "I am the owner of this property, or authorised by the owner to offer it for sale, and everything in this listing is accurate.": "我是该房产的业主，或已获业主授权出售该房产，且本房源中的所有信息均真实准确。",
  "I can get a rent guarantee policy": "我可以办理租金担保保险",
