  "I understand": "我已了解",
  "I understand: these clauses are optional. Tap a card to add it, and tap it again to remove it.": "我已了解：这些条款为可选项。点按卡片即可添加，再次点按即可移除。",
  "Identity": "身份",
  "Identity checked by OneHome": "身份已由 OneHome 核验",
  "Identity is linked from the tenant's One ID. Adjust only the dates or terms if you are making a special offer.": "身份信息来自租客的 One ID。仅在提供特别优惠时调整日期或条款。",
  "Identity review is still required before final approval.": "最终批准前仍需完成身份审核。",
  "If the problem cannot be seen — the air conditioner is not blowing cold air — photograph it anyway and say so here. A caption is what turns a photo into evidence.": "如果问题无法直接看到——比如空调不出冷风——也请照常拍照并在此说明。正是说明文字让照片成为证据。",
  "If the window closes with photos that were never answered, the photos stand as the record and the silence is recorded with them. If nobody submitted anything, there is no move-in record — and with no record, nothing can be deducted from the deposit at the end.": "如期限结束时照片仍未获回应，照片即作为记录，未回应的情况也会一并记录。如无人提交任何照片，则没有入住记录——没有记录，最终就不能从押金中扣除任何费用。",
  "If they move in mid-month, the part-month at the start.": "如果在月中入住，即开头不足一个月的部分。",
  "If you both agree, it can reopen once for another 48 hours.": "如双方同意，可再重新开启一次，为期 48 小时。",
  "If you opened the link in the same email, the code was already used — they are one and the same. Send a fresh one and type it without opening the link.": "如果您打开了同一封邮件中的链接，验证码就已被使用——两者是同一回事。请重新获取一个验证码，并在不打开链接的情况下输入。",
  "Important information about Colombian deposit law": "关于哥伦比亚押金法规的重要信息",
