  "Instagram doesn't show links in posts, so it gets a picture with the link printed on it — and the link is copied for the Link sticker.": "Instagram 不在帖子中显示链接，所以会生成一张印有链接的图片 — 链接也会被复制，供链接贴纸使用。",
