  "Let the public comment on this listing": "允许公开评论此房源",
  "Ley 820 de 2003 (Article 16) says a landlord may not require a cash deposit on a residential lease of 30 days or more. A tenant can ask for it back at any time and the clause has no force. OneHome does not collect it, hold it, or return it, and takes no fee on it — it is paid to you directly and it is between you and the tenant. The tenant is told all of this on your listing.": "Ley 820 de 2003（第 16 条）规定，对于 30 天或以上的住宅租约，房东不得要求现金押金。租客可随时要求退还，该条款不具效力。OneHome 不收取、不保管、不退还此押金，也不对其收取任何费用 — 押金直接支付给你，是你与租客之间的事。租客会在你的房源页面上看到以上所有说明。",
