  "No bed": "无床",
  "No cash changes hands to secure the lease — which is the arrangement Colombian residential law is built around.": "无需支付现金作为租约担保 — 这正是哥伦比亚住宅租赁法所依据的安排。",
  "No comments yet — ask something.": "暂无评论——来提个问题吧。",
