  "No pets": "不允许宠物",
  "No photos yet": "暂无照片",
  "No photos yet. Whoever is standing in the property should start.": "暂无照片。请由当前在房屋内的一方开始拍摄。",
  "No photos, no replies.": "没有照片，就没有回复。",
  "No places match your search.": "没有符合搜索条件的房源。",
  "No places match — loosen a filter": "没有符合条件的房源 — 请放宽筛选条件",
  "No price changes recorded yet.": "暂无价格变动记录。",
  "No price yet": "尚无价格",
  "No properties listed yet.": "尚未发布房源。",
  "No properties match this filter.": "没有符合此筛选条件的房源。",
  "No recorded sale yet. Colombia keeps no public record of what a property last sold for — when this one sells here, with the deed on file, it becomes the first entry in its permanent history.": "暂无成交记录。哥伦比亚没有公开记录房产上次的成交价 — 当这套房产在这里售出并存档契据后，这将成为其永久历史中的第一条记录。",
  "No registered sale price on file. The national registry only carries transaction values from 2021 onward, so an older or quietly-held property will show nothing here — that is not a sign of a problem.": "暂无登记成交价。国家登记处仅收录 2021 年以来的交易金额，因此较早交易或长期未转手的房产在此不会显示任何内容——这并不代表有问题。",
  "No thanks": "不用了",
  "No thanks — decline": "不用了 — 拒绝",
  "No viewing times are open for this place at the moment. You can message the host and ask — most will make time.": "目前此房源没有开放的看房时段。您可以给房东发消息询问——大多数房东都会安排时间。",
  "Nobody by that name yet.": "暂无此姓名的用户。",
  "Nobody submitted photos in time, so there is no record of how the property was. With no record, nothing can be deducted from the deposit at the end.": "无人按时提交照片，因此没有房屋状况记录。没有记录，最终就不能从押金中扣除任何费用。",
  "None chosen — your agreements will carry the required sections only.": "未选择 — 你的协议将只包含必需部分。",
  "Not connected.": "未连接。",
  "Not described yet": "尚无描述",
  "Not enough recorded sales nearby yet to estimate a range. Every sale closed here adds to it.": "附近的成交记录尚不足以估算价格区间。在这里完成的每一笔交易都会让它更完整。",
  "Not looked up. Registered sale prices are chained by matrícula inmobiliaria — the property's permanent number at the registry office, printed at the top of its certificado de tradición y libertad. This listing doesn't carry one yet, so nothing has been checked either way.": "尚未查询。登记成交价通过 matrícula inmobiliaria 关联——这是该房产在登记处的永久编号，印在其 certificado de tradición y libertad 的顶部。此房源尚未填写该编号，因此目前未做任何核查。",
  "Not ready, and we would rather say so than show you four places that aren't actually comparable. Prices in Medellín swing by several times over across neighbourhoods that sit side by side, so a comparison is only worth reading once neighbourhoods are matched exactly and the area in m² is on enough listings to divide by.": "尚未就绪。与其给您展示四个其实不可比的房源，我们宁愿直说。在麦德林，相邻街区之间的价格可能相差数倍，因此只有当街区完全匹配、且足够多的房源填写了 m² 面积可供计算时，比较才有参考价值。",
  "Not sent yet": "尚未发送",
  "Not showing": "不带看",
  "Not signed yet": "尚未签署",
  "Not started yet.": "尚未开始。",
  "Not submitted": "未提交",
  "Notary": "公证处",
  "Nothing booked yet.": "暂无预订。",
  "Nothing changes unless you accept. Accepting means the rent keeps running for the extra time.": "除非您接受，否则不会有任何变化。接受即表示租金将在延长期间继续计算。",
  "Nothing for sale here yet.": "这里暂无在售房源。",
  "Nothing here yet. Your listings and photos will appear here.": "这里还没有内容。您的房源和照片将显示在这里。",
  "Nothing is charged here. You're writing down what will be charged and when, so the tenant agrees to it before any money moves.": "此处不会扣款。你只是写明将收取哪些费用以及何时收取，让租客在任何资金流动前先表示同意。",
  "Nothing left blank": "无空白项",
  "Nothing listed yet": "暂无房源",
  "Nothing moves forward until ": "在 ",
  "Nothing saved yet": "暂无收藏",
  "Nothing saved yet.": "尚未保存任何内容。",
  "Nothing secures this lease beyond the agreement itself. That is allowed, and it is worth being deliberate about.": "除协议本身外，此租约没有其他担保。这是允许的，但值得慎重考虑。",
  "Nothing to map yet": "暂无可在地图上显示的内容",
  "Nothing was removed. This period may have changed or you may no longer have access. Refresh and try again.": "未移除任何内容。此时段可能已更改，或你可能已无访问权限。请刷新后重试。",
  "Nothing was saved. This period may have changed or you may no longer have access. Refresh and try again.": "未保存任何内容。此时段可能已更改，或你可能已无访问权限。请刷新后重试。",
  "Nothing yet.": "暂无内容。",
  "Nothing — trust only": "无 — 仅凭信任",
  "Occupancy": "入住率",
  "Of your published properties, rented today": "你已发布的房源中，今天已出租的比例",
  "Off keeps it public — the link and your profile still open it — but it stays out of the feed.": "关闭后仍为公开 — 仍可通过链接和你的个人资料打开 — 但不会出现在动态中。",
