  "OneHome does not hold the purchase price and is not a party to the sale. Listing here does not create an exclusive arrangement with us.": "OneHome 不代管购房款，也不是交易的一方。在此发布房源不构成与我们的独家约定。",
  "OneHome fee — you are covering the renter's share too": "OneHome 费用 — 您同时承担租客的部分",
