  "Shows places free from your arrival date whose minimum stay fits. It cannot see a host's existing bookings yet, so confirm the dates with them.": "显示从您入住日期起空闲且最短入住期符合的房源。暂时无法查看房东现有的预订，请与房东确认日期。",
