  "Something on OneHome still points at this place - usually a contract - so it cannot be deleted. That link is what keeps those records readable for everyone on them. Archive it instead: it leaves your working list and public search, and every record stays intact.": "OneHome 中仍有内容关联此房源（通常是合同），因此无法删除。正是这一关联让所有相关方都能查看这些记录。请改为归档：房源将从您的工作列表和公开搜索中移除，所有记录完整保留。",
  "Sort": "排序",
  "Sort by": "排序方式",
