  "Stays under 30 nights are lodging, not a home lease, so a card hold is the right instrument and the only one offered here.": "少于 30 晚的住宿属于住宿服务而非住宅租赁，因此信用卡预授权是合适的方式，也是此处唯一提供的方式。",
