  "Submitting is not final approval and does not guarantee the home.": "提交申请不代表最终批准，也不保证能租到该房源。",
  "Submitting this request does not hold the dates. The hold starts when the host pre-approves.": "提交此申请不会保留日期。房东预批准后才开始为您保留日期。",
  "Submitting…": "正在提交…",
  "Suggestions applied. Review the form, then save the draft or publish.": "已应用建议。请检查表单，然后保存草稿或发布。",
  "TRM certified by the Superintendencia Financiera, in force {0}.": "TRM 由 Superintendencia Financiera 认证，自 {0} 起生效。",
  "TRM certified by the Superintendencia Financiera, in force {0}. Saved with the listing so the price you set today still reads honestly in six months.": "TRM 由 Superintendencia Financiera 认证，自 {0} 起生效。随房源一同保存，确保您今天设定的价格在六个月后仍如实显示。",
  "Take or choose photos": "拍摄或选择照片",
  "Tap and hold to react": "长按以回应",
  "Tap any amber blank to jump to the field that fills it.": "点按任意琥珀色空白处，即可跳转到对应字段。",
  "Tap the heart on any listing and it lands here — so you can put four places side by side instead of scrolling back to find them.": "点按任意房源上的爱心，它就会出现在这里 — 这样你可以并排比较四个房源，而不必往回翻找。",
  "Tap to add": "点按添加",
  "Tap to remove": "点按移除",
  "Tap to send voice note": "点按发送语音消息",
  "Tell the tenant what needs to be corrected.": "告诉租客需要更正的内容。",
  "Tell them about your pets": "介绍一下您的宠物",
  "Tell them what it is actually like to live there — the light, the noise, the walk to the shops.": "告诉他们住在那里的真实感受 — 采光、噪音、走到商店的路程。",
  "Tenant": "租客",
