  "Twelve years in El Poblado. I answer messages the same day.": "在 El Poblado 十二年。当天回复消息。",
  "Two or three lines. This is what makes an agent reply — who you are, why you're moving, how long you plan to stay.": "两三行即可。这能让经纪人回复您 — 您是谁、为何搬家、计划住多久。",
