  "Up to 100 photos and 10 videos (five minutes each). Select large batches; original evidence quality is retained for pinch-to-zoom.": "最多 100 张照片和 10 个视频（每个五分钟）。可批量选择；保留原始画质，支持双指缩放。",
  "Up to 5 public videos. Portrait and landscape clips both open full screen.": "最多 5 个公开视频。竖屏和横屏视频均可全屏打开。",
