  "Up to {0} characters on your {1} plan. This is the caption people read in the feed.": "您的 {1} 套餐最多 {0} 个字符。这是大家在动态中看到的说明文字。",
  "Up to {0} videos · 5 minutes and 300 MB each · resumable uploads": "最多 {0} 个视频 · 每个 5 分钟、300 MB · 支持断点续传",
  "Up to {0}. The first is the cover unless you choose another below.": "最多 {0} 张。第一张为封面，除非您在下方另选。",
  "Upload your agreement": "上传您的协议",
  "Upload, paste or link an existing document. You will review every suggestion before it becomes part of this property's agreement.": "上传、粘贴或链接现有文档。每条建议在纳入此房源协议之前都会经过你的审阅。",
  "Use a 6-digit email code": "使用 6 位邮箱验证码",
