  "Use this for repairs, personal stays, or any date you cannot host. The available-again date is not blocked.": "用于维修、自住或任何无法接待的日期。“恢复可订”当天不会被封锁。",
  "Using OneHome's standard agreement. No supplemental owner terms were enabled for this property.": "使用 OneHome 标准协议。此房屋未启用任何补充业主条款。",
